8	export function hrClearCorridor() {
9	  scene.updateMatrixWorld(true);
10	  const plants = new Set<THREE.Material>([MAT.trunk, MAT.leaf, MAT.palm, MAT.lampPole, MAT.bulb]);
11	  const zero = new THREE.Matrix4().makeScale(0, 0, 0), m = new THREE.Matrix4(), p = new THREE.Vector3(), q = new THREE.Quaternion(), s = new THREE.Vector3();
12	  const half = HR.halfWidth + 3.5;    // lòng đường + vỉa hè
13	  let removed = 0;
14	  scene.traverse((obj) => {
15	    const o = obj as THREE.InstancedMesh;
16	    if (!o.isInstancedMesh) return;
17	    const building = !!o.parent && (o.parent as THREE.LOD).isLOD;
18	    if (!building && !plants.has(o.material as THREE.Material)) return;
19	    let changed = false;
20	    for (let i = 0; i < o.count; i++) {
21	      o.getMatrixAt(i, m); m.decompose(p, q, s); p.applyMatrix4(o.matrixWorld);
22	      if (Math.abs(p.x) < 262) continue;                                    // trên sông chỉ có thuyền
23	      const reach = half + (building ? s.z / 2 : 1);
24	      if (Math.abs(p.z - HR.z) < reach) { o.setMatrixAt(i, zero); changed = true; removed++; }
25	    }
26	    if (changed) o.instanceMatrix.needsUpdate = true;
27	  });
28	  return removed;
