2	import { CONFIG } from '../config';
3	import { scene } from '../core/renderer';
4	import { MAT } from '../core/materials';
5	import { rand } from '../common/math';
6	import { shadowed } from '../common/geometry';
7	import { deckY } from '../bridges/dragon/profile';
8	import { passLodAdd, passLodInfo } from '../core/passLod';
9	import { trShadeTrunkGeo, trShadeCrownLodGeo, trPalmTrunkGeo, trPalmCrownGeo, trYaw } from '../common/trees/shapes';
10	
11	/* ============================ Cây xanh & đèn đường ============================ */
12	export function buildTrees() {
13	  const round: [number, number][] = [], palms: [number, number][] = [];
14	  const B = CONFIG.bankX;
15	  for (let z = -2300; z < 2300; z += 14) {
16	    if (Math.abs(z) < 26 || Math.abs(z - CONFIG.ttl.z) < 24) continue;
17	    for (const s of [-1, 1]) {
18	      const x = s * (B + 9 + rand() * 12);
19	      ((Math.round(z / 14) % 3 === 0) ? palms : round).push([x, z]);
20	    }
21	  }
22	  for (const [x0, x1] of [[-1880, -345], [345, 1460]]) for (let x = x0; x < x1; x += 16) {
23	    for (const s of [-1, 1]) (x > 1200 ? palms : round).push([x + rand() * 3, s * 21.5]);
24	  }
25	  for (let i = 0; i < 160; i++) { // công viên hai đầu cầu
26	    const s = i % 2 ? 1 : -1; round.push([s * (345 + rand() * 120), (rand() < 0.5 ? -1 : 1) * (32 + rand() * 120)]);
27	  }
28	  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), v = new THREE.Vector3(), s = new THREE.Vector3(), col = new THREE.Color();
29	  const T = CONFIG.trees, wk = T.palm.trunkWidth, bendX = T.palm.bend * wk;
30	  // Cây bóng mát (G1): thân + cành chuẩn hóa (đầu cành cao nhất = tâm tán), tán cụm lá giữ đúng tâm / tỉ lệ quả cầu cũ (fallen.ts, promenade.ts, dọn cây đọc ma trận tán)
31	  const t1 = new THREE.InstancedMesh(trShadeTrunkGeo(), MAT.trunk, round.length);
32	  const crownLod = trShadeCrownLodGeo();   // hình học gộp [đầy đủ | thưa]: lượt bóng / phản chiếu vẽ bản thưa (src/core/passLod.ts)
33	  const c1 = new THREE.InstancedMesh(crownLod.geo, MAT.leaf, round.length);
34	  round.forEach(([x, z], i) => {
35	    const h = 3 + rand() * 2.5, r = 2.4 + rand() * 1.8;
36	    q.setFromAxisAngle(THREE.Object3D.DEFAULT_UP, trYaw(i, T.shade.seed + 2));
37	    m.compose(v.set(x, CONFIG.landY, z), q, s.set(r, h + r * 0.6, r)); t1.setMatrixAt(i, m);
38	    m.compose(v.set(x, CONFIG.landY + h + r * 0.6, z), q, s.set(r, r * 0.85, r)); c1.setMatrixAt(i, m);
39	    col.setHSL(0.27 + rand() * 0.06, 0.45, 0.35 + rand() * 0.12); c1.setColorAt(i, col);
40	  });
41	  // Cây dừa (G2): thân cong lệch bend theo +X cục bộ ⇒ tán đặt ở đỉnh thân sau khi xoay: (x, landY + h, z) + Ry(yaw)·(bend·trunkWidth, 0, 0)
