20	/* Vẽ một biển vào vùng (x, y, w, h) của canvas */
21	function paintSign(g: CanvasRenderingContext2D, x: number, y0: number, cw: number, ch: number, lines: [string, number][], bg: string) {
22	  g.fillStyle = bg; g.fillRect(x, y0, cw, ch);
23	  g.strokeStyle = '#f2f2ee'; g.lineWidth = 4; g.strokeRect(x + 5, y0 + 5, cw - 10, ch - 10);
24	  g.fillStyle = '#f2f2ee'; g.textAlign = 'center'; g.textBaseline = 'middle';
25	  let y = y0; const tot = lines.reduce((a, [, k]) => a + k, 0);
26	  for (const [txt, k] of lines) { g.font = `600 ${Math.round(ch * k / tot * 0.72)}px "Be Vietnam Pro", sans-serif`; g.fillText(txt, x + cw / 2, y + ch * k / tot / 2); y += ch * k / tot; }
27	}
28	const SIGN_W = 1024, SIGN_H = 160, VMS_H = 92, LIM_W = 128, LIM_H = 64;   // canvas biển: VMS ở trên, biển "4,5 m" ở góc dưới trái
29	/* UV của PlaneGeometry trỏ vào vùng (u0..u1, v0..v1) của canvas biển */
30	const remapUV = (g: THREE.BufferGeometry, u0: number, u1: number, v0: number, v1: number) => { const uv = g.attributes.uv; for (let i = 0; i < uv.count; i++) uv.setXY(i, u0 + (u1 - u0) * uv.getX(i), v0 + (v1 - v0) * uv.getY(i)); return g; };
