32	export function hrBuildOutdoor(bridge: HanTunnel) {
33	  const a = HR.coverHalf, c = HR.rampHalf, cp = bridge.concreteParts, M = bridge.mats;
34	  const lintelY = (x: number) => hrRoadY(x) + HR.clear + 0.2;
35	  // gom các chi tiết nhỏ hai phía để mỗi loại chỉ tốn một draw call: lam mái, dải LED, biển VMS, biển giới hạn chiều cao
36	  const slatAll: THREE.Matrix4[] = [], ledAll: THREE.BufferGeometry[] = [], signAll: THREE.BufferGeometry[] = [];
37	  const signTex = canvasTex(SIGN_W, SIGN_H, (g) => { g.fillStyle = '#10151c'; g.fillRect(0, 0, SIGN_W, SIGN_H); paintSign(g, 0, 0, SIGN_W, VMS_H, [['HẦM SÔNG HÀN', 1.15], ['60 km/h · XE MÁY ĐI LÀN PHẢI', 0.8]], '#0a3f78'); paintSign(g, 0, VMS_H + 4, LIM_W, LIM_H, [['4,5 m', 1]], '#c9201a'); });
38	  const signMat = new THREE.MeshBasicMaterial({ map: signTex, side: THREE.DoubleSide });
39	  M.textures.push(signTex);
40	  for (const s of [-1, 1]) {
41	    const x0 = s > 0 ? a : -c, x1 = s > 0 ? c : -a, west = s < 0;
42	    const tint = west ? BRICK : [0.8, 0.8, 0.8] as [number, number, number];
43	    // máng chữ U: sàn, hai tường ngoài, dải giữa (thay hành lang thoát nạn)
44	    cp.push(prepColored(extrudeAlongX([[-W, -HR.slabBelow], [W, -HR.slabBelow], [W, 0], [-W, 0]], x0, x1, 64, hrRoadY), () => 0.75));
45	    for (const z of [-1, 1]) cp.push(prepColored(fillBlock(x0, x1, HR.outerWall, z * (W - HR.outerWall / 2), -7.6, wallTop, 64), () => tint));
46	    cp.push(prepColored(fillBlock(x0, x1, HR.tubeNear * 2, 0, -7.6, (x) => hrRoadY(x) + 0.9, 64), () => 0.8));
47	    // mái lam: dầm biên + dầm giữa trên cột, lam nghiêng bước 2 m
48	    const lx0 = s > 0 ? a : -a - HR.louverLen, lc = (lx0 + lx0 + HR.louverLen) / 2;
49	    for (const z of [-W + 0.5, 0, W - 0.5]) cp.push(prepColored(bentBox(HR.louverLen, 0.5, 0.5, lc, HR.clear + 0.25, z, 40, hrRoadY), () => tint));
50	    for (let x = lx0 + 8; x < lx0 + HR.louverLen; x += 16) cp.push(prepColored(boxAt(0.6, HR.clear - 0.9, 0.6, x, hrRoadY(x) + (HR.clear + 0.9) / 2 - 0.0, 0), () => 0.8));
51	    const slats: THREE.Matrix4[] = [];
52	    for (let x = lx0 + 1; x < lx0 + HR.louverLen; x += HR.louverGap) { _q.setFromEuler(_e.set(0, 0, 0.5)); slats.push(new THREE.Matrix4().compose(_p.set(x, hrRoadY(x) + HR.clear + 0.45, 0), _q, _s.set(1, 1, 1))); }
53	    slatAll.push(...slats);
54	    // dải LED viền mái lam và cửa hầm (sáng về đêm)
55	    const px = s * (a + HR.louverLen);   // mặt cửa hầm ở đầu mái lam, phía ra mặt phố
56	    const led = [-W, W].map((z) => bentBox(HR.louverLen, 0.08, 0.08, lc, HR.clear + 0.55, z, 40, hrRoadY));
57	    led.push(boxAt(0.1, 0.1, W * 2, px, lintelY(px) + 0.1, 0));
58	    ledAll.push(...led.map((g) => { g.deleteAttribute('uv'); return g; }));
59	    // khung cửa hầm: dầm ngang + hai trụ, biển VMS quay ra phía đường dẫn
60	    cp.push(prepColored(boxAt(1.4, 1.7, W * 2 + 0.4, px, lintelY(px) + 1.1, 0), () => tint));
61	    for (const z of [-1, 1]) cp.push(prepColored(boxAt(1.6, lintelY(px) + 1.1 - wallTop(px) + 0.4, 1.6, px, (lintelY(px) + 1.1 + wallTop(px)) / 2 - 0.2, z * (W - 0.8)), () => tint));
62	    signAll.push(remapUV(new THREE.PlaneGeometry(15, 1.35), 0, 1, 1 - VMS_H / SIGN_H, 1).rotateY(s * Math.PI / 2).translate(px + s * 0.72, lintelY(px) + 1.1, 0));
63	    // trang trí đỉnh cửa hầm
