91	/* Mặt đường nối (Đống Đa phía Tây, Vân Đồn phía Đông), dải giữa, vỉa hè, đèn đường */
92	function hrBuildSurface(bridge: HanTunnel) {
93	  const Wd = HR.shoulder * 2 + HR.laneWidth * HR.lanesPerDir, c = HR.rampHalf;
94	  const roads: THREE.BufferGeometry[] = [];
95	  for (const [x0, x1, segs] of [[-1900, -780, 1], [-780, -HR.coverHalf, 80], [HR.coverHalf, 780, 80], [780, 1480, 1]] as [number, number, number][]) {
96	    roads.push(roadStrip(x0, x1, Wd, HR.tubeCenter, 0.03, segs, hrRoadY), roadStrip(x0, x1, Wd, -HR.tubeCenter, 0.03, segs, hrRoadY, true));
97	  }
98	  const road = shadowed(new THREE.Mesh(mergeGeometries(roads), bridge.mats.roadOut), false, true);
99	  road.name = 'hr-road'; bridge.group.add(road); bridge.noReflect.push(road); bridge.farHide.push(road);
100	  // dải giữa cỏ (4,2 m) và vỉa hè gạch (3 m) hai bên đường mặt phố
101	  const med: THREE.BufferGeometry[] = [], paver: THREE.BufferGeometry[] = [];
102	  for (const [x0, x1] of [[-1900, -c], [c, 1480]]) {
103	    const len = x1 - x0, xc = (x0 + x1) / 2, segs = Math.ceil(len / 8);
