106	  }
107	  bridge.concreteParts.push(...med.map((g) => prepColored(g, () => [0.4, 0.58, 0.3])), ...paver.map((g) => prepColored(g, () => [0.8, 0.72, 0.6])));
108	  const xs: number[] = []; for (let x = 760; x <= 1460; x += 40) xs.push(x, -x);
