1	import * as THREE from 'three';
2	import { shared } from '../../core/shared';
3	import { BridgeBase } from '../../common/BridgeBase';
4	import { createTraffic, stepTraffic, type Traffic } from '../../common/traffic';
5	import { boatKeepOut } from '../../environment/traffic';
6	import { HR, hrRoadY, hrInside } from './profile';
7	import { hrMaterials, hrUpdateLamps, type HrMaterials } from './materials';
8	import { buildBore, spinFans, type Bore } from './bore';
9	import { hrBuildOutdoor } from './outdoor';
10	import { hrBuildRiverbed, type Riverbed } from './riverbed';
11	import { hrClearCorridor } from './corridor';
12	import { Cutaway } from './cutaway';
13	import { ImmersionController, IM_STATES, type ImState } from './immersion';
14	
15	/* ======================================================================
16	   HẦM VƯỢT SÔNG HÀN — phương án đề xuất 2025 (chưa xây), nối Đống Đa (Hải Châu) với Vân Đồn (Sơn Trà)
17	   Group đặt tại z = −1700; tim sông là x = 0. Hầm dìm 5 đốt × 120 m qua sông, hầm kín trên bờ, hầm hở hai đầu.
18	   ====================================================================== */
19	export class HanTunnel extends BridgeBase<HrMaterials> {
20	  underground = new THREE.Group();    // vỏ + nội thất hầm kín: chỉ hiện khi camera ở trong hầm, bật mặt cắt hoặc đang mô phỏng dìm
21	  bores!: { west: Bore; mid: Bore; east: Bore };
22	  riverbed!: Riverbed;
23	  cutaway!: Cutaway;
24	  readonly cfg = HR;
25	  ctrl = new ImmersionController();
26	  traffic!: Traffic;
27	  sim = new THREE.Group();
28	  private masts: THREE.Mesh[] = [];
29	  private tugs: THREE.Group[] = [];
30	  private bulk: THREE.Mesh[] = [];
31	  private fanAngle = 0;
32	  forceInterior = false;               // Tour/UI muốn thấy nội thất bất kể vị trí camera
33	
34	  constructor() {
35	    super('HanTunnel', 'hr', HR.z, new THREE.Vector3(0, 5, HR.z), HR.lodDistance);
36	    this.mats = hrMaterials();
37	    this.farDistance = HR.farDistance;
38	    this.closable = false;           // bão: hầm vẫn lưu thông (bơm thoát nước làm việc), không theo lệnh đóng cầu
39	    hrClearCorridor();               // phải chạy trước khi dựng cọ và đèn của chính hầm
40	    // vỏ + nội thất theo ba đoạn: đốt 3 (±60 m) tách riêng để mô phỏng dìm
41	    const M = this.mats;
42	    this.bores = { west: buildBore(-HR.coverHalf, -60, M, 'hr-bore-w'), mid: buildBore(-60, 60, M, 'hr-bore-mid'), east: buildBore(60, HR.coverHalf, M, 'hr-bore-e') };
43	    this.underground.name = 'hr-underground';
44	    this.underground.add(this.bores.west.group, this.bores.mid.group, this.bores.east.group);
45	    this.underground.traverse((o) => { if ((o as THREE.Mesh).isMesh) (o as THREE.Mesh).receiveShadow = true; });
46	    this.group.add(this.underground); this.noReflect.push(this.underground);
47	    this.riverbed = hrBuildRiverbed(M);
48	    this.group.add(this.riverbed.group); this.noReflect.push(this.riverbed.group);
49	    hrBuildOutdoor(this);
50	    this.buildSim();
51	    this.traffic = createTraffic(this, { seed: 3100, x0: -1500, x1: 1480, name: 'hr-traffic', lanes: [
52	      { off: HR.laneOffsets[0], n: 34, speed: HR.carSpeed, bike: 0.03, bus: 0.12 },
53	      { off: HR.laneOffsets[1], n: 30, speed: HR.carSpeed, bike: 0.06, bus: 0.12 },
54	      { off: HR.laneOffsets[2], n: 110, speed: HR.bikeSpeed, bike: 0.94, bus: 0 }   // làn phải: xe máy
55	    ] });
56	    this.finalize();
